import React, { useState } from "react";
import toast from "react-hot-toast";

export default function TutorRegister() {
  const [name, setName] = useState("");
  const [experience, setExperience] = useState("");
  const [credentials, setCredentials] = useState("");
  const [expertise, setExpertise] = useState([]);
  const [address, setAddress] = useState("");
  const [contact, setContact] = useState("");
  const [resume, setResume] = useState(null);

  const handleSubmit = async () => {
    if (!resume) return toast.error("Please upload a resume.");

    const formData = new FormData();
    formData.append("name", name);
    formData.append("experience", experience);
    formData.append("credentials", credentials);
    formData.append("expertise_courses", JSON.stringify(expertise));
    formData.append("address", address);
    formData.append("contact_info", contact);
    formData.append("resume", resume);

    try {
      const res = await fetch("/api/register-tutor", {
        method: "POST",
        body: formData,
      });
      if (!res.ok) throw new Error("Failed to register");
      toast.success("Tutor registered successfully!");
    } catch (err) {
      toast.error(err.message);
    }
  };

  return (
    <div className="max-w-2xl mx-auto mt-10 p-6 bg-slate-800 rounded-xl shadow-xl">
      <h2 className="text-3xl font-semibold mb-4">Tutor Registration</h2>
      <input type="text" placeholder="Name" className="input" value={name} onChange={(e) => setName(e.target.value)} />
      <textarea placeholder="Experience" className="input" value={experience} onChange={(e) => setExperience(e.target.value)} />
      <textarea placeholder="Credentials" className="input" value={credentials} onChange={(e) => setCredentials(e.target.value)} />
      <div className="mb-4">
        <label className="block mb-1">Expertise Courses</label>
        <select multiple className="input h-32" value={expertise} onChange={(e) => setExpertise([...e.target.selectedOptions].map(o => o.value))}>
          {["Mathematics","Science","English","History","Programming","Art","Music"].map(c => (
            <option key={c}>{c}</option>
          ))}
        </select>
      </div>
      <input type="text" placeholder="Address" className="input" value={address} onChange={(e) => setAddress(e.target.value)} />
      <input type="text" placeholder="Contact Info" className="input" value={contact} onChange={(e) => setContact(e.target.value)} />
      <input type="file" accept=".pdf" className="input bg-slate-700" onChange={(e) => setResume(e.target.files[0])} />
      <button onClick={handleSubmit} className="btn bg-blue-500 hover:bg-blue-600">Register as Tutor</button>
    </div>
  );
}
